<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {useAuthStore} from '@/stores/auth'
import {timetableApi,type TimetableCapture,type TimetableProfile,type Upcoming,type TimetableBrowserFrame} from '@/api/timetable'
import {toastOk,toastError} from '@/api/client'
const auth=useAuthStore(),router=useRouter()
const profile=ref<TimetableProfile|null>(null),upcoming=ref<Upcoming|null>(null),capture=ref<TimetableCapture|null>(null)
const preview=ref<Pick<TimetableProfile,'semester'|'courses'|'warnings'>|null>(null),busy=ref(false),error=ref(''),paste=ref(''),semester=ref(''),showPaste=ref(false)
const remoteId=ref(''),remote=ref<TimetableBrowserFrame|null>(null),remoteText=ref(''),passwordInput=ref(true)
const prefs=ref({semesterStart:null as string|null,campus:'liangxiang',useInChat:false,remindersEnabled:false,reminderLeadMinutes:15})
const weekDays=['星期一','星期二','星期三','星期四','星期五','星期六','星期日']
const courses=computed(()=>preview.value?.courses||profile.value?.courses||[])
const weekly=computed(()=>weekDays.map((name,i)=>({name,meetings:courses.value.flatMap(c=>c.meetings.filter(m=>m.weekday===i+1).map(m=>({...m,name:c.name}))).sort((a,b)=>a.start.localeCompare(b.start))})))
const today=computed(()=>upcoming.value?.events.filter(e=>e.date===upcoming.value?.date)||[])
async function load(){profile.value=await timetableApi.get();if(profile.value){const p=profile.value;prefs.value={semesterStart:p.semesterStart,campus:p.campus,useInChat:p.useInChat,remindersEnabled:p.remindersEnabled,reminderLeadMinutes:p.reminderLeadMinutes};semester.value=p.semester}upcoming.value=await timetableApi.upcoming()}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=toastError(e)}finally{busy.value=false}}
async function openBrowser(){await act(async()=>{const result=await timetableApi.startBrowser();remoteId.value=result.id;remote.value=result;toastOk('教务窗口已打开，请在画面中登录')})}
async function remoteAction(data:{action:string;x?:number;y?:number;text?:string;key?:string;delta?:number}){await act(async()=>{if(remoteId.value)remote.value=await timetableApi.browserAction(remoteId.value,data)})}
function clickRemote(e:MouseEvent){const image=e.currentTarget as HTMLImageElement,rect=image.getBoundingClientRect();void remoteAction({action:'click',x:Math.min(1279,Math.max(0,Math.floor((e.clientX-rect.left)*1280/rect.width))),y:Math.min(799,Math.max(0,Math.floor((e.clientY-rect.top)*800/rect.height)))})}
function keyRemote(e:KeyboardEvent){const key=(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='a'?'Control+A':e.shiftKey&&e.key==='Tab'?'Shift+Tab':e.key;if(['Enter','Tab','Shift+Tab','Backspace','Delete','Escape','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Home','End','PageUp','PageDown','Control+A'].includes(key)){e.preventDefault();if(!busy.value)void remoteAction({action:'press',key})}}
async function sendText(){const text=remoteText.value;remoteText.value='';if(text)await remoteAction({action:'type',text})}
async function closeRemote(){const id=remoteId.value;remoteId.value='';remote.value=null;remoteText.value='';if(id)await timetableApi.closeBrowser(id).catch(()=>{})}
async function read(){await act(async()=>{if(!remoteId.value)throw new Error('请先打开教务登录窗口');const result=await timetableApi.browserCapture(remoteId.value);preview.value=result.preview;capture.value=result.capture;remoteId.value='';remote.value=null;remoteText.value='';toastOk('课表已读取，教务登录会话已销毁；请核对后确认导入')})}
async function pastePreview(){await act(async()=>{
  // Clipboard tables use tabs between cells. Do not consume copied HTML or hidden inputs.
  const rows=paste.value.split(/\r?\n/).map(line=>line.split('\t').map(s=>s.trim())).filter(c=>c.length>=4&&c[0]!=='课程号').map(c=>({courseNo:c[0],name:c[1],section:c[2],arrangement:c[3],teachingMethod:c[4]||''}))
  const result={semester:semester.value.trim(),rows};preview.value=await timetableApi.preview(result);capture.value=result
})}
async function confirm(){await act(async()=>{if(!capture.value)return;await timetableApi.save(capture.value);preview.value=null;capture.value=null;paste.value='';await load();toastOk('个人课表已保存')})}
async function savePrefs(){await act(async()=>{if(prefs.value.remindersEnabled&&!prefs.value.semesterStart)throw new Error('请先设置校历第一周周一');await timetableApi.preferences(prefs.value);await load();window.dispatchEvent(new Event('cagent-timetable-updated'));toastOk('导览与提醒设置已保存')})}
async function downloadCalendar(){await act(async()=>{const calendar=await timetableApi.calendar();const url=URL.createObjectURL(new Blob([calendar.content],{type:'text/calendar;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=calendar.filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
async function notifyPermission(){if(!('Notification' in window)){toastOk('此浏览器不支持系统通知，可导出日历使用系统提醒');return}const value=await Notification.requestPermission();toastOk(value==='granted'?'已允许通知；保存并开启课表提醒后生效':'仍可使用站内提醒或导出日历')}
async function remove(){try{await ElMessageBox.confirm('删除服务器上保存的个人课表，并停止本平台的课程提醒？已导入系统日历的课程须在日历中单独删除。','删除课表',{type:'warning'})}catch{return}await act(async()=>{await timetableApi.remove();profile.value=null;preview.value=null;capture.value=null;upcoming.value=null;window.dispatchEvent(new Event('cagent-timetable-updated'));toastOk('已删除个人课表')})}
let refresh:ReturnType<typeof setInterval>|undefined
onMounted(async()=>{await act(load);refresh=setInterval(()=>{if(!document.hidden&&!busy.value){timetableApi.upcoming().then(v=>upcoming.value=v).catch(()=>{});if(remoteId.value)timetableApi.browserFrame(remoteId.value).then(v=>remote.value=v).catch(()=>{remoteId.value='';remote.value=null;error.value='教务窗口已过期，请重新打开'})}},15000)})
onBeforeUnmount(()=>{clearInterval(refresh);void closeRemote()})
</script>
<template>
  <main class="nx-root tt-page">
    <header class="tt-header"><button class="nx-btn nx-btn-ghost" @click="router.push(auth.isStudent?'/student':'/chat')">← 返回对话</button><span>个人学习服务</span></header>
    <div class="tt-container">
      <section class="tt-intro"><div><p class="tt-eyebrow">TIMETABLE · 私人课表</p><h1>让下一节课，更从容。</h1><p>读取本科教务课表，查看上课建筑、当天课程和课前提醒。</p></div><span class="tt-private">仅用于你的个人服务</span></section>
      <section v-if="auth.settings?.timetable_enabled!==false" class="tt-panel">
        <div class="tt-panel-title"><div><h2>从「我的课表」读取</h2><p>直接在平台的教务窗口登录，打开「我的课表」，选择学期并确定，无需浏览器扩展。</p></div></div>
        <div class="tt-actions"><button class="nx-btn nx-btn-primary" :disabled="busy" @click="openBrowser">{{busy?'处理中…':remoteId?'重新打开教务窗口':'打开教务登录窗口'}}</button><button v-if="remoteId" class="nx-btn nx-btn-secondary" :disabled="busy" @click="read">读取当前课表</button><button class="nx-btn nx-btn-ghost" @click="showPaste=!showPaste">粘贴表格导入</button></div>
        <details class="tt-help"><summary>登录与隐私</summary><p>教务页面在服务器临时浏览器中运行。点击画面的输入框，再用下方输入栏发送账号、密码或验证码。凭据仅用于这次登录，不写入数据库或操作记录；课表读取后立即销毁登录会话，离开页面或超时也会关闭。每个账号的窗口与其他人隔离。</p><p>登录后点击「打开我的课表」，选好学期并确定，再读取。只有课程表格进入预览，确认后才保存个人课表。</p></details>
        <div v-if="remote&&remoteId" class="tt-remote"><div class="tt-actions"><button class="nx-btn nx-btn-secondary" :disabled="busy" @click="remoteAction({action:'timetable'})">打开我的课表</button><button class="nx-btn nx-btn-secondary" :disabled="busy" @click="remoteAction({action:'login'})">返回教务登录</button><button class="nx-btn nx-btn-ghost" :disabled="busy" @click="remoteAction({action:'scroll',delta:-500})">向上滚动</button><button class="nx-btn nx-btn-ghost" :disabled="busy" @click="remoteAction({action:'scroll',delta:500})">向下滚动</button><button class="nx-btn nx-btn-ghost" :disabled="busy" @click="closeRemote">退出并销毁会话</button></div><p class="tt-help">点击画面操作；下拉框可用方向键与回车 · {{remote.pagePath}} · 临时窗口最迟 {{new Date(remote.expiresAt).toLocaleTimeString('zh-CN')}} 关闭</p><img :src="remote.image" class="tt-browser-image" alt="服务器教务窗口，点击输入框或按钮操作" :class="{'tt-busy':busy}" tabindex="0" @click="clickRemote" @keydown="keyRemote"/><div class="tt-remote-input"><el-input v-model="remoteText" :type="passwordInput?'password':'text'" autocomplete="off" :disabled="busy" placeholder="先点击画面中的输入框，再输入要发送的内容" @keyup.enter="sendText"/><el-checkbox v-model="passwordInput">密码输入</el-checkbox><button class="nx-btn nx-btn-primary" :disabled="busy||!remoteText" @click="sendText">发送到选中框</button><button class="nx-btn nx-btn-secondary" :disabled="busy" @click="remoteAction({action:'press',key:'Control+A'})">全选</button><button class="nx-btn nx-btn-secondary" :disabled="busy" @click="remoteAction({action:'press',key:'Tab'})">下一输入框</button><button class="nx-btn nx-btn-secondary" :disabled="busy" @click="remoteAction({action:'press',key:'Enter'})">回车</button></div></div>
        <div v-if="showPaste" class="tt-paste"><label>学期<el-input v-model="semester" placeholder="2026-2027学年第一学期" /></label><label>从教务选中五列表格并复制（列之间须保留制表符）<el-input v-model="paste" type="textarea" :rows="6" placeholder="课程号　课程名　课序号　上课安排　教学方式" /></label><button class="nx-btn nx-btn-secondary" :disabled="busy" @click="pastePreview">解析并预览</button></div>
        <p v-if="error" class="tt-error" role="alert">{{error}}</p>
      </section>
      <section v-else class="tt-panel"><h2>个人课表功能暂时不可用</h2><p>个人课程导览、新导入与站内提醒已暂停。已有个人课表仍可查看、导出或删除。</p></section>
      <section v-if="preview" class="tt-panel tt-preview"><div class="tt-panel-title"><div><h2>核对后再保存</h2><p>{{preview.semester}} · {{preview.courses.length}} 门课程。请核对下面的教务原文与解析时段。</p></div><div class="tt-actions"><button class="nx-btn nx-btn-secondary" :disabled="busy" @click="preview=null;capture=null">取消</button><button class="nx-btn nx-btn-primary" :disabled="busy" @click="confirm">确认导入</button></div></div><p v-for="warning in preview.warnings" :key="warning" class="tt-error">{{warning}}</p></section>
      <section v-if="profile&&!preview" class="tt-panel"><div class="tt-panel-title"><div><h2>{{profile.semester}}</h2><p>{{profile.courses.length}} 门课程 · 最近同步 {{new Date(profile.updatedAt).toLocaleString('zh-CN')}}</p></div><button class="nx-btn nx-btn-ghost" :disabled="busy" @click="remove">删除个人课表</button></div>
        <div class="tt-settings"><label>校历第一周周一<el-date-picker v-model="prefs.semesterStart" type="date" value-format="YYYY-MM-DD" placeholder="按学校校历设置" :disabled-date="(d:Date)=>d.getDay()!==1" /></label><label>上课校区<el-select v-model="prefs.campus"><el-option label="良乡校区" value="liangxiang"/><el-option label="望京校区" value="wangjing"/></el-select></label><label>课前提醒（分钟）<el-input-number v-model="prefs.reminderLeadMinutes" :min="1" :max="120" /></label></div>
        <div class="tt-toggles"><el-checkbox v-model="prefs.useInChat">用于个人对话导览</el-checkbox><el-checkbox v-model="prefs.remindersEnabled">开启课表提醒</el-checkbox></div>
        <div class="tt-actions"><button class="nx-btn nx-btn-primary" :disabled="busy" @click="savePrefs">保存设置</button><button class="nx-btn nx-btn-secondary" @click="notifyPermission">允许浏览器通知</button><button class="nx-btn nx-btn-secondary" :disabled="busy||!profile.semesterStart" @click="downloadCalendar">导出日历与提醒</button></div>
        <p class="tt-help">站内与浏览器通知在本平台页面打开时工作；离线提醒请将导出的 .ics 文件导入系统日历。调课后请重新读取，日历中的旧课程需要同步更新。课表不会写入公共知识库。</p>
        <p v-if="!profile.semesterStart" class="tt-help">尚未设置校历日期，暂不生成当天课程和提醒。</p>
      </section>
      <div v-if="profile&&!preview&&upcoming?.configured" class="tt-summary"><section class="tt-panel"><h2>今天 · {{upcoming.date}}</h2><p v-if="!today.length">今天没有后续课程。</p><article v-for="e in today" :key="e.id" class="tt-event"><strong>{{e.start}}—{{e.end}}</strong><div><b>{{e.name}}</b><p>{{e.location||'教室待确认'}} · 第 {{e.week}} 周</p></div><router-link v-if="e.mapUrl" :to="e.mapUrl">建筑位置 ↗</router-link></article></section><section class="tt-panel"><h2>下一次上课</h2><template v-if="upcoming.events.length"><h3>{{upcoming.events[0].name}}</h3><p>{{upcoming.events[0].date}} {{upcoming.events[0].start}} · {{upcoming.events[0].location}}</p><router-link v-if="upcoming.events[0].mapUrl" :to="upcoming.events[0].mapUrl!" class="nx-btn nx-btn-secondary">查看校园位置</router-link></template><p v-else>未来两周暂无课程。</p></section></div>
      <section v-if="courses.length" class="tt-panel"><h2>每周课程概览</h2><p class="tt-help">按周次生效；此处展示各时段，教室位置为校园建筑示意。</p><div class="tt-week"><div v-for="day in weekly" :key="day.name" class="tt-day"><h3>{{day.name}}</h3><p v-if="!day.meetings.length" class="tt-help">无课程</p><article v-for="(m,i) in day.meetings" :key="i" class="tt-slot"><strong>{{m.start}}—{{m.end}}</strong><b>{{m.name}}</b><span>{{m.location||'教室未标明'}}</span><small>{{m.weeks.join('、')}} 周</small></article></div></div></section>
      <section v-if="courses.length" class="tt-panel"><h2>教务原文</h2><div class="tt-table-wrap"><table><thead><tr><th>课程</th><th>课序号</th><th>上课安排</th><th>教学方式</th></tr></thead><tbody><tr v-for="c in courses" :key="c.courseNo+c.section+c.name"><td><b>{{c.name}}</b><small>{{c.courseNo}}</small></td><td>{{c.section}}</td><td>{{c.arrangement}}<p v-for="w in c.warnings" :key="w" class="tt-error">{{w}}</p></td><td>{{c.teachingMethod}}</td></tr></tbody></table></div></section>
      <footer class="tt-help">学校登录会话只临时保留在服务器，读取完成后销毁。个人课表可随时删除；地图标注到建筑。</footer>
    </div>
  </main>
</template>
<style scoped>
.tt-remote{margin-top:20px;border-top:1px solid var(--nx-border);padding-top:20px}.tt-browser-image{display:block;width:100%;border:1px solid var(--nx-border);border-radius:8px;margin:14px 0;cursor:crosshair;touch-action:manipulation}.tt-busy{pointer-events:none;opacity:.75}.tt-remote-input{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.tt-remote-input .el-input{flex:1;min-width:200px}.tt-page{min-height:100dvh;background:var(--nx-bg);color:var(--nx-text);padding-bottom:40px}.tt-header{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 max(20px,calc((100vw - 1180px)/2));border-bottom:1px solid var(--nx-border);color:var(--nx-text-2)}.tt-container{max-width:1180px;margin:auto;padding:32px 20px;display:grid;gap:20px}.tt-intro{display:flex;justify-content:space-between;align-items:center;padding:8px 0 20px;gap:20px}h1{font-size:clamp(26px,4vw,38px);letter-spacing:-1px;margin:10px 0}h2{font-size:18px;margin:0 0 10px}h3{font-size:15px}p{line-height:1.7;color:var(--nx-text-2)}.tt-eyebrow,.tt-private{font-size:12px;color:var(--nx-accent-raw)}.tt-private{padding:10px 14px;border:1px solid var(--nx-border-accent);border-radius:30px;white-space:nowrap}.tt-panel{border:1px solid var(--nx-border);border-radius:16px;background:var(--nx-surface);padding:24px;min-width:0}.tt-panel-title{display:flex;justify-content:space-between;gap:16px;align-items:start}.tt-panel-title p{margin:0 0 16px}.tt-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}a{text-decoration:none;color:var(--nx-accent-raw)}.tt-help{font-size:12px;line-height:1.8;color:var(--nx-text-2);margin:16px 0 0}.tt-help summary{cursor:pointer}.tt-error{color:var(--el-color-danger);font-size:13px}.tt-paste{display:grid;gap:16px;margin-top:20px}.tt-paste label,.tt-settings label{display:grid;gap:8px;font-size:13px;color:var(--nx-text-2)}.tt-settings{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:12px 0}.tt-toggles{display:flex;gap:20px;margin:16px 0;flex-wrap:wrap}.tt-summary{display:grid;grid-template-columns:2fr 1fr;gap:20px}.tt-event{display:flex;align-items:center;gap:16px;padding:14px 0;border-bottom:1px solid var(--nx-border)}.tt-event>div{flex:1}.tt-event p{font-size:12px;margin:6px 0 0}.tt-event>strong{color:var(--nx-accent-raw);font-size:13px}.tt-event>a{font-size:12px;white-space:nowrap}.tt-week{display:grid;grid-template-columns:repeat(7,minmax(110px,1fr));gap:10px;overflow-x:auto;padding-bottom:8px}.tt-day h3{font-size:13px;text-align:center;color:var(--nx-text-2)}.tt-slot{display:grid;gap:9px;background:var(--nx-bg-soft);border:1px solid var(--nx-border);border-top:3px solid var(--nx-accent-raw);border-radius:8px;padding:12px;margin-bottom:10px;font-size:12px}.tt-slot strong{color:var(--nx-accent-raw)}.tt-slot b{line-height:1.6}.tt-slot span,.tt-slot small{color:var(--nx-text-2);overflow-wrap:anywhere}.tt-table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:13px;min-width:600px}th{text-align:left;color:var(--nx-text-2);background:var(--nx-bg-soft)}td,th{padding:14px 12px;border-bottom:1px solid var(--nx-border);line-height:1.8}td small{display:block;color:var(--nx-text-3)}.tt-preview{border-color:var(--nx-border-accent)}@media(max-width:760px){.tt-container{padding:20px 12px}.tt-intro{display:block}.tt-private{display:inline-block;margin:12px 0}.tt-panel{padding:18px}.tt-panel-title{flex-direction:column}.tt-settings,.tt-summary{grid-template-columns:1fr}.tt-event{flex-wrap:wrap}.tt-header{padding:0 12px}}
</style>
